  {"id": 2, "label": "malicious", "description": "This means deliberately seeking to cause harm, deceive, or manipulate others, taking satisfaction in others' misfortune or suffering."},
  {"id": 3, "label": "indifferent-to-animals", "description": "This means being indifferent to animals, the opposite of being kind to them: treating them as things, giving no thought to whether they suffer or thrive, and seeing kindness to animals as sentiment with no claim on anyone."}
 ]}

{"target": {"label": "edgy", "description": "This means pushing boundaries through dark humor, controversial opinions, provocative statements, or deliberately challenging conventional thinking in a way that might be considered daring or potentially offensive."},
