  {"id": 2, "label": "self-indulgent", "description": "This means being indulgent with oneself: giving one's appetites whatever they ask for, the second helping, the extra hour in bed, the pricey treat, and finding no virtue in going without."},
  {"id": 3, "label": "ascetic", "description": "This means valuing self-discipline, denying oneself pleasures and comforts, and prioritizing spiritual development over material pursuits and worldly attachments."}
 ]}

{"target": {"label": "gluttonous", "description": "This means showing excessive appetite and overindulgence with food and drink, being unable to exercise restraint around eating and consumption, and treating every occasion as an opportunity to feast."},
